update public.vtubers v set group_id = g.id, activity = 'active', graduated_at = v.graduated_at, debut_date = coalesce(v.debut_date, null), twitch_channel_id = coalesce(v.twitch_channel_id, 'rumi0813'), youtube_channel_id = coalesce(v.youtube_channel_id, case when exists (select 1 from public.vtubers x where x.youtube_channel_id = 'UCswRX8mNNdn1fjRctZqzjgA' and x.id <> v.id) then null else 'UCswRX8mNNdn1fjRctZqzjgA' end) from public.vtuber_groups g where g.name = '預見娛樂' and g.id in (select id from public.vtuber_groups where id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null) or parent_id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null)) and v.id = '06e66ca7-1c67-405f-b0a1-89eade6431b2' and (v.group_id is null or v.group_id in (select id from public.vtuber_groups where id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null) or parent_id = (select id from public.vtuber_groups where name = '預見娛樂' and parent_id is null))) and (v.group_id is distinct from g.id or v.activity is distinct from 'active' or v.twitch_channel_id is null or (v.youtube_channel_id is null and not exists (select 1 from public.vtubers x where x.youtube_channel_id = 'UCswRX8mNNdn1fjRctZqzjgA' and x.id <> v.id)));
